#!/usr/bin/env node
// Reads the versioned YAML data files from ../data (the repo root) and writes
// plain JSON into src/generated/ for the Astro pages/components to import.
//
// This is the ONLY place the site touches the YAML — src/generated/ is
// gitignored and regenerated by `npm run predev` / `npm run prebuild`. Never
// hand-edit files under src/generated/; edit the YAML in ../data instead and
// re-run this script (or just `npm run dev` / `npm run build`, which run it
// automatically).

import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { load as loadYamlDoc } from "js-yaml";

const __dirname = dirname(fileURLToPath(import.meta.url));
const SITE_ROOT = join(__dirname, "..");
const REPO_ROOT = join(SITE_ROOT, "..");
const DATA_DIR = join(REPO_ROOT, "data");
const OUT_DIR = join(SITE_ROOT, "src", "generated");

function loadYaml(filename) {
  const raw = readFileSync(join(DATA_DIR, filename), "utf8");
  return loadYamlDoc(raw);
}

function writeJson(filename, data) {
  writeFileSync(join(OUT_DIR, filename), JSON.stringify(data, null, 2) + "\n");
}

mkdirSync(OUT_DIR, { recursive: true });

const catalogue = loadYaml("ntra_catalogue.yml");
const infrastructure = loadYaml("infrastructure_catalogue.yml");
const reforms = loadYaml("reform_initiatives.yml");

const artefacts = catalogue.entries;
const catalogueVersion = catalogue["catalogue-version"];

// Join: for every infrastructure entry, find which artefacts reference it,
// split by status, so the Infrastructure page can show "currently captures
// credit for" vs "planned to capture credit for" without a manually
// maintained field.
const infrastructureEnriched = infrastructure.map((infra) => {
  const activeFor = [];
  const plannedFor = [];

  for (const artefact of artefacts) {
    for (const ref of artefact["supporting-infrastructure"] ?? []) {
      if (ref["infrastructure-id"] !== infra.id) continue;
      const entry = {
        id: artefact.id,
        artefact: artefact.artefact,
        category: artefact.category,
        captureFunction: ref["capture-function"],
      };
      if (ref.status === "active") activeFor.push(entry);
      else if (ref.status === "planned") plannedFor.push(entry);
    }
  }

  return { ...infra, activeFor, plannedFor };
});

const categories = [...new Set(artefacts.map((a) => a.category))];

const stats = {
  catalogueVersion,
  artefactCount: artefacts.length,
  categoryCount: categories.length,
  infrastructureCount: infrastructure.length,
  reformInitiativeCount: reforms.length,
  categories,
};

writeJson("ntra-catalogue.json", { catalogueVersion, artefacts });
writeJson("infrastructure-catalogue.json", infrastructureEnriched);
writeJson("reform-initiatives.json", reforms);
writeJson("stats.json", stats);

console.log(
  `build-data: wrote ${artefacts.length} artefacts, ${infrastructure.length} infrastructure entries, ${reforms.length} reform initiatives (catalogue v${catalogueVersion})`
);
